"""
Real-Time Adaptive Signal Processing Algorithm for Non-Stationary Time Series.

Filtering functions return samples aligned to input indices window_size-1
through len(x)-1.
"""
import numpy as np


def _as_finite_1d(x):
    a = np.asarray(x, dtype=float).reshape(-1)
    if a.size == 0:
        return a
    if np.all(np.isfinite(a)):
        return a
    good = np.isfinite(a)
    if not np.any(good):
        return np.zeros_like(a)
    return np.interp(np.arange(a.size), np.flatnonzero(good), a[good])


def adaptive_filter(x, window_size=20):
    x = _as_finite_1d(x)
    if len(x) < window_size:
        raise ValueError(
            f"Input signal length ({len(x)}) must be >= window_size ({window_size})"
        )
    return np.convolve(
        x, np.ones(window_size, dtype=float) / float(window_size), mode="valid"
    )


def _centered_fallback(x, cutoff=0.08):
    n = len(x)
    try:
        from scipy.signal import butter, sosfiltfilt
        sos = butter(3, cutoff, btype="lowpass", output="sos")
        return sosfiltfilt(sos, x, padlen=min(n - 1, 12))
    except Exception:
        span = min(n if n % 2 else n - 1, 15)
        if span < 3:
            return x.copy()
        p = span // 2
        return np.convolve(
            np.pad(x, (p, p), mode="edge"),
            np.ones(span, dtype=float) / float(span),
            mode="valid",
        )


def _hysteretic_trend(full):
    """Suppress isolated opposite derivative excursions without quantization."""
    n = len(full)
    if n < 3:
        return full

    dy = np.diff(full)
    center = np.median(dy)
    scale = 1.4826 * np.median(np.abs(dy - center))
    if not np.isfinite(scale) or scale <= 1e-12:
        return full

    deadband = 0.85 * scale
    out = np.empty(n, dtype=float)
    out[0] = full[0]
    direction = 0
    pending = 0.0

    for i in range(1, n):
        step = full[i] - full[i - 1]
        if not np.isfinite(step):
            step = 0.0
        sign = 1 if step > 0 else (-1 if step < 0 else 0)

        if direction == 0:
            if sign:
                direction = sign
            out[i] = full[i]
        elif sign == 0 or sign == direction:
            pending = 0.0
            out[i] = full[i]
        else:
            pending += step
            if abs(pending) >= deadband:
                direction = sign
                pending = 0.0
                out[i] = full[i]
            else:
                out[i] = out[i - 1]

    return out


def enhanced_filter_with_trend_preservation(x, window_size=20):
    x = _as_finite_1d(x)
    n = len(x)
    if n < window_size:
        raise ValueError(
            f"Input signal length ({n}) must be >= window_size ({window_size})"
        )
    if n <= 2:
        return x[window_size - 1:].copy()

    dx = np.diff(x)
    diff_med = np.median(dx)
    diff_scale = 1.4826 * np.median(np.abs(dx - diff_med))
    signal_scale = 1.4826 * np.median(np.abs(x - np.median(x))) + 1e-12
    noise_ratio = max(0.0, diff_scale / (np.sqrt(2.0) * signal_scale))
    cutoff = float(np.clip(0.12 / (1.0 + 1.8 * noise_ratio), 0.055, 0.12))

    full = None
    try:
        from scipy.interpolate import UnivariateSpline

        if n < 4:
            full = _centered_fallback(x, cutoff)
        else:
            t = np.arange(n, dtype=float)
            sigma = np.median(np.abs(dx - diff_med)) / (0.67448975 * np.sqrt(2.0))
            sigma = max(float(sigma), 1e-12)
            order = min(3, n - 1)
            base_budget = float(n * sigma * sigma)

            # Deterministic blocked validation avoids selecting flexibility
            # solely because it follows in-sample noise.
            choices = (0.45, 0.8, 1.35, 2.3)
            scored = []
            positions = np.arange(n)
            for mult in choices:
                errors = []
                budget = base_budget * mult
                try:
                    for fold in range(5):
                        valid = (positions % 5) == fold
                        train = ~valid
                        if np.count_nonzero(train) <= order:
                            continue
                        fit = UnivariateSpline(
                            t[train], x[train],
                            w=np.ones(np.count_nonzero(train)),
                            s=budget, k=order,
                        )
                        pred = np.asarray(fit(t[valid]), dtype=float)
                        if np.all(np.isfinite(pred)):
                            errors.extend(np.abs(x[valid] - pred))
                    if errors:
                        scored.append((float(np.median(errors)), mult))
                except Exception:
                    pass

            if not scored:
                raise RuntimeError("no valid spline candidate")

            mult = min(scored, key=lambda z: z[0])[1]
            weights = np.ones(n, dtype=float)
            estimate = None
            for _ in range(2):
                fit = UnivariateSpline(
                    t, x, w=weights, s=base_budget * mult, k=order
                )
                estimate = np.asarray(fit(t), dtype=float)
                residual = x - estimate
                rscale = 1.4826 * np.median(
                    np.abs(residual - np.median(residual))
                )
                threshold = 1.345 * max(sigma, float(rscale), 1e-12)
                weights = np.minimum(
                    1.0, threshold / (np.abs(residual) + 1e-12)
                )
            if estimate is None or not np.all(np.isfinite(estimate)):
                raise RuntimeError("invalid spline estimate")
            full = estimate
    except Exception:
        full = _centered_fallback(x, cutoff)

    full = np.asarray(full, dtype=float)[:n]
    if full.size != n or not np.all(np.isfinite(full)):
        full = x.copy()

    full = _hysteretic_trend(full)
    return full[window_size - 1:]


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    np.random.seed(seed)
    t = np.linspace(0, 10, length)
    clean_signal = (
        2 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2 * t)
        + 0.5 * np.sin(2 * np.pi * 5 * t)
        + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t)
    )
    clean_signal += 0.1 * t * np.sin(0.2 * t)
    clean_signal += np.cumsum(np.random.randn(length) * 0.05)
    noisy_signal = clean_signal + np.random.normal(0, noise_level, length)
    return noisy_signal, clean_signal


def run_signal_processing(noisy_signal=None, signal_length=1000,
                          noise_level=0.3, window_size=20):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(signal_length, noise_level)
    else:
        noisy_signal = _as_finite_1d(noisy_signal)
        clean_signal = None

    filtered_signal = process_signal(noisy_signal, window_size, "enhanced")

    if clean_signal is None:
        return {
            "filtered_signal": filtered_signal,
            "clean_signal": None,
            "noisy_signal": None,
            "correlation": 0,
            "noise_reduction": 0,
            "signal_length": len(filtered_signal),
        }

    delay = window_size - 1
    aligned_clean = clean_signal[delay:]
    aligned_noisy = noisy_signal[delay:]
    m = min(len(filtered_signal), len(aligned_clean))
    filtered_signal = filtered_signal[:m]
    aligned_clean = aligned_clean[:m]
    aligned_noisy = aligned_noisy[:m]

    correlation = (
        np.corrcoef(filtered_signal, aligned_clean)[0, 1]
        if m > 1 and np.std(filtered_signal) > 0 and np.std(aligned_clean) > 0
        else 0
    )
    noise_before = np.var(aligned_noisy - aligned_clean)
    noise_after = np.var(filtered_signal - aligned_clean)
    noise_reduction = (
        (noise_before - noise_after) / noise_before if noise_before > 0 else 0
    )

    return {
        "filtered_signal": filtered_signal,
        "clean_signal": aligned_clean,
        "noisy_signal": aligned_noisy,
        "correlation": correlation,
        "noise_reduction": noise_reduction,
        "signal_length": m,
    }


if __name__ == "__main__":
    results = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {results['correlation']:.3f}")
    print(f"Noise reduction: {results['noise_reduction']:.3f}")
    print(f"Processed signal length: {results['signal_length']}")

